//! 🧪️ The actual declared native Window App opens, donates its original allocation and closes under mounted authority.
use crate::fixture;
use semio_framework_plugin_decl_app::ArtifactApp;
use semio_framework_plugin_instance_app::{OriginalVcsApp,original_instance_admission::{OriginalSingleWindowRegistration,original_instance_factory}};
use semio_framework_plugin_reactor_app::{PluginApp,PluginAppDelegate,OriginalPluginAppSource};
use semio_framework_plugin_window_kits::RegisteredAppDefinition;
use semio_framework_os_kernel::NoMembers;
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
type App=fixture::NativeWindowApp;
type Recipient=OriginalVcsApp<App,NoMembers>;
type Registration=OriginalSingleWindowRegistration<App,NoMembers,fixture::Owner>;
const POLICY:semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1=semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT;
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,action:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->(T,RetainedCloneProgress){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,action));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual native mounted owner physical receipt {p:?}, failure={:?}",result.as_ref().err());(result.unwrap(),p)}
#[test]fn actual_native_window_app_opens_and_closes_with_its_original_registered_sources(){
 let factory=original_instance_factory::<App,NoMembers,Recipient,Registration>();
 let((mut definition,mut registration),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut definition=semio_framework_async::poll::resolve_ready(semio_framework_manifest_app_surface::testkit::app_with(Vec::new(),Vec::new()));definition.id=App::APP_ID.into();definition.controller_id=definition.id.clone();definition.dialect=App::DIALECT.into();definition.io.artifact_schema=App::DOCUMENT_SCHEMA.into();let mut definition=RegisteredAppDefinition::declared(definition,true);let mut registration=(factory.registration)(definition.original_source().unwrap()).unwrap();definition.commit_producer();registration.commit_producer();(definition,registration)});
 let initial=heap.requested_bytes-heap.released_bytes;
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(44711),Generation(78),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:4096},default_now_us,u64::MAX,1<<30);
 let mut decoder=OriginalJobDecodeOwner::empty();let mut construction=None;let mut app=None;let(mut born,mut released)=(0,0);
 for index in 0..1048576{let(_,p)=turn(&mut caller,&mut decoder,POLICY.preparation,|cx|{if let Some(construction)=construction.as_mut(){let source=definition.original_source().unwrap();construction.advance(OriginalPluginAppSource{definition:&source,definition_source:definition.original_source().unwrap(),registration:registration.as_ref(),actor:"native-window-actor",instance_id:77,policy:POLICY},cx,&mut app)?;}else{(factory.begin)(cx,&mut construction)?;}Ok(())});born+=p.retained_capacity_bytes;released+=p.released_bytes;if app.is_some(){break}assert!(index<1048575,"actual declared native App opening did not finish");}
 assert!(app.is_some());assert_eq!(app.as_ref().unwrap().delegate_ref().snapshot_ref().zoom,1.25);
 for index in 0..1048576{if construction.as_ref().unwrap().terminal_is_empty(){break}let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|construction.as_mut().unwrap().close_step(cx).map(|_|())));born+=p.retained_capacity_bytes;released+=p.released_bytes;assert!(index<1048575,"actual native opening retained its original sources after donation");}
 let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|{let d=construction.as_ref().unwrap().boxed_release_demands()?;close_original_retained_step(cx,d,|_|{drop(construction.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));born+=p.retained_capacity_bytes;released+=p.released_bytes;
 for index in 0..1048576{if app.as_ref().unwrap().close_terminal_is_empty(){break}let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|{let grant=cx.retained_grant();app.as_mut().unwrap().close_step(cx,grant).map_err(OriginalTurnFailure::from)?;Ok(())}));born+=p.retained_capacity_bytes;released+=p.released_bytes;assert!(index<1048575,"actual native App retained an original payload or physical Box");}assert!(app.take().unwrap().close_terminal_is_empty());
 for index in 0..1048576{if registration.terminal_is_empty(){break}let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|registration.close_step(cx).map(|_|())));born+=p.retained_capacity_bytes;released+=p.released_bytes;assert!(index<1048575,"actual native tool producer retained an instance alias");}
 let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|{let d=registration.boxed_release_demands();close_original_retained_step(cx,d,|_|{drop(registration);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));born+=p.retained_capacity_bytes;released+=p.released_bytes;
 for index in 0..1048576{if definition.terminal_is_empty(){break}let(_,p)=turn(&mut caller,&mut decoder,POLICY.close,|cx|cx.with_original_retirement(|cx|{let d=definition.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|definition.close_step(g))?;Ok(())}));born+=p.retained_capacity_bytes;released+=p.released_bytes;assert!(index<1048575,"actual native definition retained an instance alias");}
 while !decoder.terminal_is_empty(){let result=caller.turn(POLICY.close,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())}));result.unwrap();}
 assert_eq!(initial+born,released,"actual declaration and native instance graphs must close physically");caller.retire(POLICY.close);
}
